name: Auto triage new issues
on:
  issues:
    types: [opened]
permissions:
  issues: write
jobs:
  triage:
    runs-on: ubuntu-latest
    steps:
      - name: Determine labels
        id: determine
        uses: actions/github-script@v6
        with:
          script: |
            const title = context.payload.issue.title.toLowerCase();
            const body = (context.payload.issue.body || '').toLowerCase();
            const text = title + ' ' + body;
            const typeKeywords = {
              bug: ['bug', 'error', 'crash', 'broken', 'fix', 'fail', 'wrong', 'regression'],
              feature: ['feat', 'feature', 'enhancement', 'add', 'implement', 'request', 'improve']
            };
            const priorityKeywords = {
              high: ['critical', 'urgent', 'blocker', 'blocking', 'severe', 'p0', 'p1'],
              low: ['minor', 'trivial', 'nice to have', 'low priority', 'p3', 'p4']
            };
            let type = 'feature-request';
            if (typeKeywords.bug.some(k => text.includes(k))) {
              type = 'bug';
            } else if (typeKeywords.feature.some(k => text.includes(k))) {
              type = 'feature-request';
            }
            let priority = 'priority: medium';
            if (priorityKeywords.high.some(k => text.includes(k))) {
              priority = 'priority: high';
            } else if (priorityKeywords.low.some(k => text.includes(k))) {
              priority = 'priority: low';
            }
            core.setOutput('type', type);
            core.setOutput('priority', priority);
      - name: Create missing labels
        uses: actions/github-script@v6
        with:
          script: |
            const labels = [
              {name: 'bug', color: 'd73a4a'},
              {name: 'feature-request', color: 'a2eeef'},
              {name: 'priority: high', color: 'ff0000'},
              {name: 'priority: medium', color: 'f9d0c4'},
              {name: 'priority: low', color: '0e8a16'}
            ];
            const existing = await github.issues.listLabelsForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo
            });
            const existingNames = existing.data.map(l => l.name);
            for (const lbl of labels) {
              if (!existingNames.includes(lbl.name)) {
                await github.issues.createLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: lbl.name,
                  color: lbl.color
                });
              }
            }
      - name: Add labels to issue
        uses: actions-ecosystem/action-add-labels@18f1af5e3544586314bbe15c0273249c770b2daf
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          labels: "${{ steps.determine.outputs.type }},${{ steps.determine.outputs.priority }}"
          repo: ${{ github.repository }}
          number: ${{ github.event.issue.number }}
